module Moderate
  class BaseController < ApplicationController
    before_action :authenticate_moderator!

    layout "moderate"

    private

    def authenticate_moderator!
      expected_user = ENV["QUIZZY_MODERATOR_USERNAME"].to_s
      expected_pass = ENV["QUIZZY_MODERATOR_PASSWORD"].to_s

      authenticate_or_request_with_http_basic("Quizzy Moderator") do |username, password|
        next false if expected_user.empty? || expected_pass.empty?

        ActiveSupport::SecurityUtils.secure_compare(username.to_s, expected_user) &
          ActiveSupport::SecurityUtils.secure_compare(password.to_s, expected_pass)
      end
    end
  end
end
module Moderate
  class PreviewsController < BaseController
    layout "preview"

    before_action :set_quiz
    before_action :set_active_questions

    def show
      @state_token = params[:state].presence
      @state = decode_state(@state_token)
      @total = @active_questions.size

      return if @total.zero?

      if @state[:finished]
        @score = @state[:score]
        render :score
      else
        step = @state[:step].clamp(0, @total - 1)
        @step = step
        @question = @active_questions[step]
        @picked_option = @question.options.find { |opt| opt.id == @state[:picked_id] } if @state[:picked_id]
      end
    end

    def pick
      return redirect_to(moderate_quiz_preview_path(@quiz), status: :see_other) if @active_questions.empty?

      state = decode_state(params[:state])
      step = state[:step].clamp(0, @active_questions.size - 1)
      question = @active_questions[step]

      if state[:picked_id].present?
        redirect_to moderate_quiz_preview_path(@quiz, state: encode_state(state)), status: :see_other
        return
      end

      option = question.options.find_by(id: params[:option_id])
      unless option
        redirect_to moderate_quiz_preview_path(@quiz, state: encode_state(state)), status: :see_other
        return
      end

      new_state = {
        step: step,
        score: state[:score] + (option.correct? ? 1 : 0),
        picked_id: option.id,
        finished: false
      }

      redirect_to moderate_quiz_preview_path(@quiz, state: encode_state(new_state)), status: :see_other
    end

    def next
      return redirect_to(moderate_quiz_preview_path(@quiz), status: :see_other) if @active_questions.empty?

      state = decode_state(params[:state])
      next_step = state[:step] + 1

      new_state = if next_step >= @active_questions.size
        { step: @active_questions.size - 1, score: state[:score], picked_id: nil, finished: true }
      else
        { step: next_step, score: state[:score], picked_id: nil, finished: false }
      end

      redirect_to moderate_quiz_preview_path(@quiz, state: encode_state(new_state)), status: :see_other
    end

    def finish
      return redirect_to(moderate_quiz_preview_path(@quiz), status: :see_other) if @active_questions.empty?

      state = decode_state(params[:state])
      new_state = { step: state[:step], score: state[:score], picked_id: nil, finished: true }

      redirect_to moderate_quiz_preview_path(@quiz, state: encode_state(new_state)), status: :see_other
    end

    private

    def set_quiz
      @quiz = Quiz.find(params[:quiz_id])
    end

    def set_active_questions
      @active_questions = @quiz.active_questions.includes(:options).to_a
    end

    def preview_verifier
      Rails.application.message_verifier(:quizzy_preview)
    end

    def encode_state(state)
      preview_verifier.generate(state.stringify_keys)
    end

    def decode_state(token)
      default = { step: 0, score: 0, picked_id: nil, finished: false }
      return default if token.blank?

      data = preview_verifier.verify(token)
      {
        step: [ data["step"].to_i, 0 ].max,
        score: [ data["score"].to_i, 0 ].max,
        picked_id: data["picked_id"]&.to_i,
        finished: data["finished"] == true
      }
    rescue ActiveSupport::MessageVerifier::InvalidSignature
      default
    end
  end
end
module Moderate
  class QuizzesController < BaseController
    before_action :set_quiz, only: [ :show, :edit, :update, :destroy, :export ]

    def index
      @quizzes = Quiz.includes(:questions).order(created_at: :desc, id: :desc)
    end

    def show
      @questions = @quiz.questions.includes(:options).order(:position, :id)
    end

    def new
      @quiz = Quiz.new
    end

    def create
      @quiz = Quiz.new(quiz_params)
      if @quiz.save
        redirect_to moderate_quiz_path(@quiz), notice: "Quiz created."
      else
        render :new, status: :unprocessable_entity
      end
    end

    def edit
    end

    def update
      if @quiz.update(quiz_params)
        redirect_to moderate_quiz_path(@quiz), status: :see_other, notice: "Quiz saved."
      else
        render :edit, status: :unprocessable_entity
      end
    end

    def destroy
      @quiz.destroy!
      redirect_to moderate_root_path, status: :see_other, notice: "Quiz deleted."
    end

    def export
      @export_json = JSON.pretty_generate(@quiz.export_payload)
    end

    def import
      @quiz_json = ""
      @import = QuizImport.new
    end

    def create_import
      @quiz_json = params[:quiz_json].to_s
      @import = QuizImport.new(@quiz_json)

      if @import.save
        redirect_to moderate_quiz_path(@import.quiz), notice: "Quiz imported."
      else
        render :import, status: :unprocessable_entity
      end
    end

    private

    def set_quiz
      @quiz = Quiz.find(params[:id])
    end

    def quiz_params
      params.require(:quiz).permit(:title)
    end
  end
end
